54	function rateLimit(tier) {
55	  const max = RATE_LIMITS[tier] || RATE_LIMITS.read;
56	  return (req, res, next) => {
57	    const key = `${tier}:${req.ip}`;
58	    const now = Date.now();
59	    let entry = rateLimitMap.get(key);
60	    if (!entry || now - entry.start > RATE_LIMIT_WINDOW) {
61	      entry = { start: now, count: 0 };
62	      rateLimitMap.set(key, entry);
63	    }
64	    entry.count++;
65	    if (entry.count > max) {
66	      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
67	    }
68	    next();
69	  };
70	}
